query:
mutation UpdatePost($id: ID!, $authorId: ID!, $updatedPostContent: UpdatedPostContent!) {
  updatePost(
    id: $id
    authorId: $authorId
    updatedPostContent: $updatedPostContent
  ) {
    id
    title
    content
    updatedAt
  }
}

